slug":"dealer"},{"type_slug":"identity","person_type_slug":"rental_provider"},{"type_slug":"identity","person_type_slug":"music_publisher"},{"type_slug":"identity","person_type_slug":"a_and_r"},{"type_slug":"identity","person_type_slug":"other"},{"type_slug":"professional","person_type_slug":"singer"},{"type_slug":"professional","person_type_slug":"rapper"},{"type_slug":"professional","person_type_slug":"folk_vocalist"},{"type_slug":"professional","person_type_slug":"voice_artist"},{"type_slug":"professional","person_type_slug":"musician"},{"type_slug":"professional","person_type_slug":"guitarist"},{"type_slug":"professional","person_type_slug":"bassist"},{"type_slug":"professional","person_type_slug":"keyboardist"},{"type_slug":"professional","person_type_slug":"drummer"},{"type_slug":"professional","person_type_slug":"sitarist"},{"type_slug":"professional","person_type_slug":"violinist"},{"type_slug":"professional","person_type_slug":"flautist"},{"type_slug":"professional","person_type_slug":"composer"},{"type_slug":"professional","person_type_slug":"lyricist"},{"type_slug":"professional","person_type_slug":"arranger"},{"type_slug":"professional","person_type_slug":"music_director"},{"type_slug":"professional","person_type_slug":"producer"},{"type_slug":"professional","person_type_slug":"beatmaker"},{"type_slug":"professional","person_type_slug":"sound_engineer"},{"type_slug":"professional","person_type_slug":"mixing_engineer"},{"type_slug":"professional","person_type_slug":"mastering_engineer"},{"type_slug":"professional","person_type_slug":"sound_designer"},{"type_slug":"professional","person_type_slug":"dj"},{"type_slug":"professional","person_type_slug":"rj"},{"type_slug":"professional","person_type_slug":"podcaster"},{"type_slug":"professional","person_type_slug":"music_teacher"},{"type_slug":"professional","person_type_slug":"other"},{"type_slug":"business","person_type_slug":"studio"},{"type_slug":"business","person_type_slug":"music_label"},{"type_slug":"business","person_type_slug":"venue"},{"type_slug":"business","person_type_slug":"event_organizer"},{"type_slug":"business","person_type_slug":"booking_agency"},{"type_slug":"business","person_type_slug":"artist_manager"},{"type_slug":"business","person_type_slug":"production_house"},{"type_slug":"business","person_type_slug":"music_school"},{"type_slug":"business","person_type_slug":"dealer"},{"type_slug":"business","person_type_slug":"rental_provider"},{"type_slug":"business","person_type_slug":"music_publisher"},{"type_slug":"business","person_type_slug":"a_and_r"},{"type_slug":"studio","person_type_slug":"studio"},{"type_slug":"studio","person_type_slug":"venue"},{"type_slug":"studio","person_type_slug":"rental_provider"}]$json$;
BEGIN
  IF EXISTS (SELECT 1 FROM jsonb_to_recordset(payload) AS r(type_slug text, person_type_slug text)
             WHERE NOT EXISTS (SELECT 1 FROM public.taxonomy_options o
                               WHERE o.category_key = 'person_types' AND o.slug = r.person_type_slug)) THEN
    RAISE EXCEPTION 'verification_type_person_types: a person type is not in the taxonomy';
  END IF;
  INSERT INTO public.verification_type_person_types (type_slug, person_type_slug)
  SELECT r.type_slug, r.person_type_slug FROM jsonb_to_recordset(payload) AS r(type_slug text, person_type_slug text)
  ON CONFLICT (type_slug, person_type_slug) DO NOTHING;

  IF (SELECT count(*) FROM jsonb_to_recordset(payload) AS r(type_slug text, person_type_slug text) JOIN public.verification_type_person_types t ON t.type_slug = r.type_slug AND t.person_type_slug = r.person_type_slug)
     <> jsonb_array_length(payload) THEN
    RAISE EXCEPTION 'verification_type_person_types import: payload rows are missing';
  END IF;
END
$import$;
